import{_ as t,o as a,c as r,ag as o}from"./chunks/framework.Dh3ZG9qC.js";const u=JSON.parse('{"title":"界面与状态条接入","description":"","frontmatter":{},"headers":[],"relativePath":"development/ui.md","filePath":"development/ui.md","lastUpdated":null}'),d={name:"development/ui.md"};function i(l,e,s,n,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="界面与状态条接入" tabindex="-1">界面与状态条接入 <a class="header-anchor" href="#界面与状态条接入" aria-label="Permalink to &quot;界面与状态条接入&quot;">​</a></h1><p>插件界面应融入工作台的紧凑操作方式：常用动作直接可见，可选内容按需展开，减少嵌套弹窗和重复操作。</p><h2 id="选择界面方式" tabindex="-1">选择界面方式 <a class="header-anchor" href="#选择界面方式" aria-label="Permalink to &quot;选择界面方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>适用场景</th><th>执行边界</th></tr></thead><tbody><tr><td>declarative</td><td>简单表单、按钮和参数操作</td><td>宿主根据清单渲染</td></tr><tr><td>iframe</td><td>独立技术栈、需要页面隔离的插件</td><td>沙盒页面，经受控桥通信</td></tr><tr><td>core 宿主模块</td><td>与主工作台深度集成的可信 UI</td><td>与主页面共享执行环境，需 <code>ui.host</code> 权限</td></tr></tbody></table><p>官方模块通过 <code>ui/entry.js</code> 提供 SDK 版本和面板。共享依赖清单位于 <code>sdk/ui/host-modules.json</code>，复用宿主的 Vue 与状态，避免另一份 Vue 或互不相通的 store。</p><p>宿主模块清单需声明 UI 入口和宿主 UI API 版本。模块只在插件 Running 且获授权时接入；页面内不替换已有编辑实例，更新后保存并刷新。</p><h2 id="布局与控件" tabindex="-1">布局与控件 <a class="header-anchor" href="#布局与控件" aria-label="Permalink to &quot;布局与控件&quot;">​</a></h2><ul><li>常规控件以 28px 高度为基准，正文约 13px、说明约 12px，保证暗色背景上的对比度。</li><li>必填参数直接展示，可选参数和返回值通过一致的内联展开方式编辑。</li><li>密集步骤操作可用图标并提供名称提示；菜单中的操作使用清晰文字。</li><li>输入控件应有 label、焦点提示、校验反馈；错误尽量就地展示，并能定位到对应字段。</li><li>保存、运行等相邻按钮保持高度和样式体系一致，避免同一行出现无理由的尺寸差异。</li></ul><p>详细尺寸、颜色与交互见<a href="https://github.com/jesongit/gamer/blob/main/docs/design/gamer-ui-spec.md" target="_blank" rel="noreferrer">界面设计规范</a>。</p><h2 id="轻状态反馈" tabindex="-1">轻状态反馈 <a class="header-anchor" href="#轻状态反馈" aria-label="Permalink to &quot;轻状态反馈&quot;">​</a></h2><p>状态条左侧用于 Core 相关操作，右侧用于插件相关操作。插件可以反馈当前资源保存结果、步骤状态、匹配结果或运行错误，并提供复制、详情、跳转等小操作。</p><p>不要把运行、停止等主工具栏按钮再放一遍，也不要持续展示与当前操作无关的状态列表。信息应能在窄空间裁切，悬停查看完整内容。</p><p>iframe 通过 UI 桥的 <code>status.set</code> 提交声明式状态；复制和详情使用数据描述，不传函数或 HTML。具体消息字段以 <a href="https://github.com/jesongit/gamer/blob/main/sdk/ui/README.md" target="_blank" rel="noreferrer">iframe SDK</a> 和源码为准。</p><h2 id="iframe-安全与调试" tabindex="-1">iframe 安全与调试 <a class="header-anchor" href="#iframe-安全与调试" aria-label="Permalink to &quot;iframe 安全与调试&quot;">​</a></h2><p>保留 <code>sandbox=&quot;allow-scripts&quot;</code> 与严格 CSP，通过专属 MessagePort 调用能力。不要为方便换肤增加 <code>allow-same-origin</code>。</p><p>修改 SDK 示例的模板、脚本或样式后，执行 <code>node tools/build-ui-sdk.mjs</code> 重新生成自包含页面和 CSP 哈希；直接改生成文件的内联内容会使哈希失效。</p>',16)])])}const m=t(d,[["render",i]]);export{u as __pageData,m as default};
